-- Resolve historical single-person assignments when a matching current profile exists.
-- Joint assignments remain visible through legacy_assignee_names instead of being guessed.
UPDATE public.sharpening_jobs AS job
SET assigned_to = profile.id
FROM public.profiles AS profile
WHERE job.created_by IS NULL
  AND job.assigned_to IS NULL
  AND job.legacy_assignee_names IS NOT NULL
  AND position('&' IN job.legacy_assignee_names) = 0
  AND (
    lower(btrim(coalesce(profile.full_name, ''))) = lower(btrim(job.legacy_assignee_names))
    OR split_part(lower(coalesce(profile.email, '')), '@', 1) = lower(btrim(job.legacy_assignee_names))
  );

