-- Connect warranty-sheet returns to the best matching normal repair without collapsing either record.
WITH warranty_sources AS (
  SELECT warranty.id,
    (
      SELECT source.id
      FROM public.repair_tickets AS source
      WHERE source.id <> warranty.id
        AND source.is_warranty = false
        AND (
          source.ticket_number = regexp_replace(warranty.ticket_number, '-W$', '')
          OR lower(btrim(source.tool_code)) = lower(btrim(warranty.tool_code))
        )
      ORDER BY
        CASE WHEN source.ticket_number = regexp_replace(warranty.ticket_number, '-W$', '') THEN 0 ELSE 1 END,
        source.date_received_by_client DESC
      LIMIT 1
    ) AS source_id
  FROM public.repair_tickets AS warranty
  WHERE warranty.is_warranty = true AND warranty.warranty_source_ticket_id IS NULL
)
UPDATE public.repair_tickets AS warranty
SET warranty_source_ticket_id = warranty_sources.source_id
FROM warranty_sources
WHERE warranty.id = warranty_sources.id AND warranty_sources.source_id IS NOT NULL;

